import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.CFuv5BrO.js";const m=JSON.parse('{"title":"Phase 1 · Minimum Complete MVP","description":"Deliver the smallest complete product that passes at least 10 of 15 cross-industry real tasks.","frontmatter":{"title":"Phase 1 · Minimum Complete MVP","description":"Deliver the smallest complete product that passes at least 10 of 15 cross-industry real tasks.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-1.md","filePath":"en/delivery/stage-1.md","lastUpdated":1794017073000}'),o={name:"en/delivery/stage-1.md"};function l(i,e,h,n,d,p){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="phase-1-·-minimum-complete-mvp" tabindex="-1">Phase 1 · Minimum Complete MVP <a class="header-anchor" href="#phase-1-·-minimum-complete-mvp" aria-label="Permalink to &quot;Phase 1 · Minimum Complete MVP&quot;">​</a></h1><h2 id="current-status" tabindex="-1">Current status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current status&quot;">​</a></h2><p>Phase 1 has been accepted. All 15 cross-industry tasks ran and 13 passed, meeting the 10/15 hard threshold. T07 failed because its test file was not committed, and the T08 comment action still awaits approval; both remain open boundaries. See the <a href="/hearth-os/en/log/day-04.html">Day04 development log</a>.</p><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Phase 1 delivers the smallest complete product that a real user can use every day in a browser. It starts from 15 cross-industry real tasks and must pass at least 10 of them, covering the full path from creating a task through execution, approval, artifact review, and failure recovery. The goal is not broad coverage; it is proving that one task, approval, artifact, and recovery system works across multiple task families.</p><p>This phase has four steps:</p><table tabindex="0"><thead><tr><th>Step</th><th>Goal</th></tr></thead><tbody><tr><td><a href="/hearth-os/en/delivery/stage-1/1-1.html">1.1 Define the first scenario and real tasks</a></td><td>Define the first user, 15 real tasks, non-goals, and acceptance criteria.</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-1/1-2.html">1.2 Build the complete experience prototype</a></td><td>Walk through tasks, approval, artifacts, and recovery in a clickable prototype.</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-1/1-3.html">1.3 Complete the smallest real task loop</a></td><td>Let a task execute, ask for approval, produce results, and recover from failure.</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-1/1-4.html">1.4 Accept the MVP with real tasks</a></td><td>Make the first user independent of the developer.</td></tr></tbody></table><h2 id="how-to-do-it" tabindex="-1">How to do it <a class="header-anchor" href="#how-to-do-it" aria-label="Permalink to &quot;How to do it&quot;">​</a></h2><ol><li>Choose the first user and 15 cross-industry real tasks, then define acceptance with real inputs.</li><li>Walk the full path and every important state through a clickable prototype.</li><li>Complete the real task loop: execution, approval, artifacts, and failure recovery.</li><li>Have the first user use it for a week and accept the MVP with at least 10 of the 15 tasks.</li></ol>',9)])])}const u=t(o,[["render",l]]);export{m as __pageData,u as default};
